/* MH TOP worker, 2026-10-06. Append after the existing top-page styles.
   Opt in only on main[data-mh-top="shelf-v1"]. No shared navigation rules.
   Existing raster assets and DOM links are retained; no new image generation. */
main[data-mh-top="shelf-v1"] #packages {
  --top-world: url('assets/hunter-frontier-environment-r2-v1.png');
  height: clamp(420px, 28vw, 520px);
  min-height: 420px;
  padding: 0;
  overflow: hidden;
  background: linear-gradient(90deg, #060a0ede 0%, #080c1070 28%, #080c1020 58%, #080b0f40),
    linear-gradient(0deg, #100c08b8, transparent 38%), var(--top-world) center 42% / cover;
}
main[data-mh-top="shelf-v1"] #packages::after {
  height: 38px;
  border-top: 2px solid #9a7649;
  background: linear-gradient(#d7b07140, #19120dec 62%), var(--wood) center 88% / 100% auto;
  box-shadow: 0 -2px 8px #0008, inset 0 3px 2px #d4ad5d40;
}
main[data-mh-top="shelf-v1"] #packages .hero-copy {
  left: 2.8%; top: 9%; width: 22%; padding: 0;
}
main[data-mh-top="shelf-v1"] #packages .hero-copy h1 {
  font-size: clamp(36px, 3.5vw, 62px);
  line-height: 1.38; letter-spacing: .035em; margin: 0 0 18px;
}
main[data-mh-top="shelf-v1"] #packages .hero-copy p {
  font-size: clamp(11px, .9vw, 15px); line-height: 1.85; white-space: normal;
}
main[data-mh-top="shelf-v1"] #packages .section-kicker {
  font-size: 9px; letter-spacing: .15em; margin-bottom: 10px;
}
main[data-mh-top="shelf-v1"] #packages .hero-copy .english {
  font-size: 8px; line-height: 1.8; margin: 14px 0 20px;
}
main[data-mh-top="shelf-v1"] #packages .hero-copy .brass-button {
  display: flex; width: 95%; max-width: 250px; min-height: 46px;
}
main[data-mh-top="shelf-v1"] #packages .hero-whisper {
  right: 2.5%; top: 7%; font-size: clamp(12px, 1.2vw, 20px);
  max-width: 20%; white-space: normal;
}
main[data-mh-top="shelf-v1"] #packages .cases {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr)) minmax(0, 1.6fr) minmax(0, 1.12fr);
  align-items: end; gap: .3%;
  position: absolute; left: 25%; right: 2.3%; bottom: 44px;
  height: 82%; margin: 0; padding: 0;
  overflow: visible; perspective: 1600px;
}
main[data-mh-top="shelf-v1"] #packages .case {
  width: 100%; min-width: 0; height: 62%; margin: 0;
  transform: rotate(var(--rot)) rotateY(-8deg);
  transform-origin: 50% 100%;
  border: 1px solid #a28452; border-radius: 2px;
  background: linear-gradient(90deg, #080b0a 0 3%, #baa06a 4%, #463a26 7%, #14150f 11%);
  box-shadow: inset 0 0 0 2px #15130e, 3px 0 0 #554732, 6px 2px 0 #201d15,
    0 5px 4px #000b, 9px 15px 17px #0008;
  transition: transform 180ms ease, border-color 180ms ease;
}
main[data-mh-top="shelf-v1"] #packages .case::before {
  content: ''; left: 7px; top: 7px; width: 16px; height: 16px;
  border-top: 2px solid #c6a366; border-left: 2px solid #c6a366;
}
main[data-mh-top="shelf-v1"] #packages .case::after {
  inset: 5px; border-color: #c5a66580;
  background: linear-gradient(115deg, #ffffe512, transparent 20% 78%, #05080830);
}
main[data-mh-top="shelf-v1"] #packages .case .face {
  inset: 9px 6px 40px 11px;
  border-color: #9d8355; box-shadow: inset 0 0 10px #0006;
}
main[data-mh-top="shelf-v1"] #packages .case .face img {
  display: block; width: 100%; height: 100%; object-fit: contain;
}
main[data-mh-top="shelf-v1"] #packages .case .name {
  left: 9px; right: 5px; bottom: 19px;
  font-size: clamp(8px, .78vw, 13px); letter-spacing: .035em;
}
main[data-mh-top="shelf-v1"] #packages .case .state {
  left: 7%; right: 4%; bottom: -10px; padding: 5px 2px;
  font-size: clamp(7px, .52vw, 9px); letter-spacing: .02em; line-height: 1.35;
}
main[data-mh-top="shelf-v1"] #packages .case.world { --rot: -6deg; }
main[data-mh-top="shelf-v1"] #packages .case.iceborne {
  --rot: -3deg; height: 68%; border-color: #bdd5d4;
  box-shadow: inset 0 0 0 2px #192827, 3px 0 0 #79918d, 6px 2px 0 #243333,
    0 5px 4px #000b, 9px 15px 17px #0008;
}
main[data-mh-top="shelf-v1"] #packages .case.rise { --rot: -4deg; height: 66%; }
main[data-mh-top="shelf-v1"] #packages .case.sunbreak { --rot: -6deg; height: 64%; }
main[data-mh-top="shelf-v1"] #packages .case.sunbreak .name { font-size: clamp(7px, .62vw, 10px); }
main[data-mh-top="shelf-v1"] #packages .case.wilds {
  --rot: 4deg; height: 92%; z-index: 3; border-color: #d4b476;
}
main[data-mh-top="shelf-v1"] #packages .case.wilds .face { bottom: 60px; }
main[data-mh-top="shelf-v1"] #packages .case.wilds .name {
  bottom: 34px; font-size: clamp(16px, 1.35vw, 25px); letter-spacing: .12em;
}
main[data-mh-top="shelf-v1"] #packages .case.wilds .state {
  bottom: 5px; font-size: clamp(8px, .64vw, 11px);
}
main[data-mh-top="shelf-v1"] #packages .case.ascendance { --rot: 7deg; height: 51%; }
main[data-mh-top="shelf-v1"] #packages .case.ascendance .face { bottom: 57px; }
main[data-mh-top="shelf-v1"] #packages .case.ascendance .name { bottom: 34px; font-size: clamp(7px, .66vw, 11px); }
main[data-mh-top="shelf-v1"] #packages .case.ascendance .state { bottom: 5px; }
main[data-mh-top="shelf-v1"] #packages .shelf-note {
  left: 2.8%; bottom: 8px; margin: 0; max-width: 90%; font-size: 9px;
}
main[data-mh-top="shelf-v1"] #packages .case:hover {
  transform: rotate(var(--rot)) rotateY(-8deg);
}
main[data-mh-top="shelf-v1"] #packages .case:focus-visible {
  transform: rotate(var(--rot)) rotateY(-8deg) translateY(-4px);
  outline: 3px solid #ffe1a0; outline-offset: 5px; z-index: 6;
}
/* Workbench is the second zone of the same base, with original documents intact. */
main[data-mh-top="shelf-v1"] #current {
  position: relative; padding: 26px 3% 32px;
  border-top: 1px solid #9d784c;
  background: linear-gradient(#0c100ddb, #14110be8), var(--wood) center 80% / cover;
  box-shadow: inset 0 8px 18px #0009;
}
main[data-mh-top="shelf-v1"] #current .current-header { margin-bottom: 20px; }
main[data-mh-top="shelf-v1"] #current .current-title { padding: 0; }
main[data-mh-top="shelf-v1"] #current .current-title strong { margin: 9px 0; }
main[data-mh-top="shelf-v1"] #current .current-grid {
  grid-template-columns: minmax(0, 2.2fr) minmax(280px, 1fr); gap: 14px;
}
main[data-mh-top="shelf-v1"] #current .books {
  grid-column: 1; grid-row: 1 / 3; align-self: stretch;
  grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px;
}
main[data-mh-top="shelf-v1"] #current .book { min-height: 300px; }
main[data-mh-top="shelf-v1"] #current .log { grid-column: 2; grid-row: 1; }
main[data-mh-top="shelf-v1"] #current .tier { grid-column: 2; grid-row: 2; }
main[data-mh-top="shelf-v1"] #current .tier-paper {
  display: flex; flex-direction: column; align-items: stretch; gap: 9px; min-height: 0;
}
main[data-mh-top="shelf-v1"] #current .tier-paper p { font-size: 13px; margin: 0; }
main[data-mh-top="shelf-v1"] #current .tier-paper .brass-button { min-width: 0; width: 100%; max-width: none; }
main[data-mh-top="shelf-v1"] #current .panel-head { white-space: normal; flex-wrap: wrap; }
main[data-mh-top="shelf-v1"] #current .metrics { flex-wrap: wrap; }
main[data-mh-top="shelf-v1"] #future {
  border-top: 1px solid #8d7146; box-shadow: inset 0 12px 22px #0009;
}
main[data-mh-top="shelf-v1"] #future .next-card {
  border: 0; border-left: 2px solid #b2945c; background: linear-gradient(90deg, #090e12df, #090e1260);
  box-shadow: none; padding: 20px; grid-template-columns: 130px minmax(0, 1fr);
}
main[data-mh-top="shelf-v1"] #future .next-card img {
  border: 1px solid #ae905c; box-shadow: 3px 0 #3e3424, 0 8px 10px #0008;
}
main[data-mh-top="shelf-v1"] #future .next-card h3 { overflow-wrap: anywhere; }
main[data-mh-top="shelf-v1"] #history {
  background: linear-gradient(90deg, #16120be8, #10170ff0), var(--wood) center 88% / cover;
}
@media (hover: hover) {
  main[data-mh-top="shelf-v1"] #packages .case:hover {
    transform: rotate(var(--rot)) rotateY(-8deg) translateY(-4px); border-color: #e6c582; z-index: 6;
  }
}
@media (max-width: 1100px) {
  main[data-mh-top="shelf-v1"] #packages { height: 460px; min-height: 460px; }
  main[data-mh-top="shelf-v1"] #packages .hero-copy { width: 24%; top: 9%; }
  main[data-mh-top="shelf-v1"] #packages .hero-copy h1 { font-size: 35px; }
  main[data-mh-top="shelf-v1"] #packages .cases { left: 28%; right: 3%; height: 77%; }
  main[data-mh-top="shelf-v1"] #packages .hero-whisper { font-size: 12px; }
  main[data-mh-top="shelf-v1"] #current .current-grid { grid-template-columns: minmax(0, 1fr); }
  main[data-mh-top="shelf-v1"] #current .books { grid-column: 1; grid-row: 1; }
  main[data-mh-top="shelf-v1"] #current .log { grid-column: 1; grid-row: 2; }
  main[data-mh-top="shelf-v1"] #current .tier { grid-column: 1; grid-row: 3; }
  main[data-mh-top="shelf-v1"] #current .tier-paper { flex-direction: row; flex-wrap: wrap; align-items: center; }
  main[data-mh-top="shelf-v1"] #current .tier-paper .brass-button { width: auto; }
  main[data-mh-top="shelf-v1"] #future .next-card { grid-template-columns: 85px minmax(0, 1fr); gap: 14px; padding: 15px; }
}
@media (max-width: 760px) {
  main[data-mh-top="shelf-v1"] #packages { height: auto; min-height: 0; padding-top: 28px; background-position: 60% center; }
  main[data-mh-top="shelf-v1"] #packages .hero-copy { position: relative; left: auto; top: auto; width: auto; padding: 0 6%; }
  main[data-mh-top="shelf-v1"] #packages .hero-copy h1 { font-size: clamp(35px, 7vw, 48px); }
  main[data-mh-top="shelf-v1"] #packages .hero-copy .english { margin: 10px 0 15px; }
  main[data-mh-top="shelf-v1"] #packages .hero-copy .brass-button { width: 220px; }
  main[data-mh-top="shelf-v1"] #packages .hero-whisper { display: none; }
  main[data-mh-top="shelf-v1"] #packages .cases {
    position: relative; left: auto; right: auto; bottom: auto; width: 100%; height: 330px;
    display: flex; gap: 12px; margin: 8px 0 0; padding: 24px 7% 43px;
    overflow-x: auto; overflow-y: hidden; scroll-snap-type: x proximity;
    scroll-padding-inline: 7%; scrollbar-color: #aa8955 #151812; scrollbar-width: thin;
  }
  main[data-mh-top="shelf-v1"] #packages .case {
    width: 126px; min-width: 126px; flex: 0 0 126px; height: 200px; scroll-snap-align: center;
  }
  main[data-mh-top="shelf-v1"] #packages .case.iceborne { height: 216px; }
  main[data-mh-top="shelf-v1"] #packages .case.rise { height: 207px; }
  main[data-mh-top="shelf-v1"] #packages .case.sunbreak { height: 202px; }
  main[data-mh-top="shelf-v1"] #packages .case.wilds { width: 168px; min-width: 168px; flex-basis: 168px; height: 254px; }
  main[data-mh-top="shelf-v1"] #packages .case.ascendance { width: 135px; min-width: 135px; flex-basis: 135px; height: 172px; }
  main[data-mh-top="shelf-v1"] #packages .case .name { font-size: 10px; }
  main[data-mh-top="shelf-v1"] #packages .case.sunbreak .name { font-size: 8px; }
  main[data-mh-top="shelf-v1"] #packages .case.wilds .name { font-size: 19px; }
  main[data-mh-top="shelf-v1"] #packages .case.ascendance .name { font-size: 9px; }
  main[data-mh-top="shelf-v1"] #packages .case .state,
  main[data-mh-top="shelf-v1"] #packages .case.wilds .state { font-size: 8px; }
  main[data-mh-top="shelf-v1"] #packages .shelf-note { position: relative; left: auto; bottom: auto; padding: 8px 6% 12px; max-width: none; background: #12100bc0; }
  main[data-mh-top="shelf-v1"] #packages::after { bottom: 40px; pointer-events: none; }
  main[data-mh-top="shelf-v1"] #current .books { grid-template-columns: 1fr; gap: 16px; }
  main[data-mh-top="shelf-v1"] #current .book { min-height: 255px; }
  main[data-mh-top="shelf-v1"] #future .next-grid { grid-template-columns: 1fr; }
  main[data-mh-top="shelf-v1"] #current,
  main[data-mh-top="shelf-v1"] #future,
  main[data-mh-top="shelf-v1"] #history { padding: 26px 6%; }
  main[data-mh-top="shelf-v1"] #history { display: block; }
  main[data-mh-top="shelf-v1"] #history .brass-button { width: 100%; min-width: 0; margin-top: 20px; }
}
@media (prefers-reduced-motion: reduce) {
  main[data-mh-top="shelf-v1"] #packages .case { transition: none; }
  main[data-mh-top="shelf-v1"] #packages .cases { scroll-behavior: auto; scroll-snap-type: none; }
  main[data-mh-top="shelf-v1"] #packages .case:hover,
  main[data-mh-top="shelf-v1"] #packages .case:focus-visible { transform: rotate(var(--rot)) rotateY(-8deg); }
}

/* Notebook emblems only. New original raster emblems, not official weapon art.
   Appended to the current top-shelf-v1.css by the integrator; 48 source files retained.
   No page text, parchment, book background, route, or layout group changes. */
main[data-mh-top="shelf-v1"] #current .books > .book > .book-icon {
  width: min(104px, 100%); height: 104px; aspect-ratio: 1; flex: 0 0 104px;
  margin: 13px auto; border: 0; border-radius: 0; box-shadow: none; transform: none;
  background-color: transparent; background-position: center; background-repeat: no-repeat;
  filter: grayscale(.35) sepia(.35) contrast(1.15); mix-blend-mode: multiply;
}
main[data-mh-top="shelf-v1"] #current .books > .book:nth-child(1) > .book-icon {
  background-image: url('data:image/png;base64,');
  background-size: 81%;
}
main[data-mh-top="shelf-v1"] #current .books > .book:nth-child(2) > .book-icon {
  background-image: url('data:image/png;base64,');
  background-size: 100%;
}
main[data-mh-top="shelf-v1"] #current .books > .book:nth-child(3) > .book-icon {
  background-image: url('data:image/png;base64,');
  background-size: 78%;
}
@media (min-width: 761px) and (max-width: 1100px) {
  main[data-mh-top="shelf-v1"] #current .books > .book > .book-icon {
    width: min(88px, 100%); height: 88px; flex-basis: 88px;
  }
}

/* Visible glyph size only. Append after the existing emblem CSS.
   Reuses the exact existing PNG data URIs; no generated/replaced art.
   The invisible original flow box keeps titles, actions and paper dimensions. */
main#main[data-mh-top="shelf-v1"] #current .books > .book > .book-icon {
  position: static;
  background-size: 0 0;
  filter: none;
  mix-blend-mode: normal;
}
main#main[data-mh-top="shelf-v1"] #current .books > .book > .book-icon::before {
  content: "";
  display: block;
  position: absolute;
  pointer-events: none;
  left: 56%;
  top: 52.5%;
  width: auto;
  height: min(48%, 220px, calc(100% - 204px));
  aspect-ratio: var(--glyph-ratio);
  transform: translate(-50%, -50%);
  background-image: inherit;
  background-size: var(--glyph-size);
  background-position: var(--glyph-position);
  background-repeat: no-repeat;
  filter: grayscale(.35) sepia(.35) contrast(1.15);
  mix-blend-mode: multiply;
}
/* PNG alpha>16 bounds measured from the existing 1254x1254 images.
   Scale width/height together so the visible bounds exactly fill this field. */
main#main[data-mh-top="shelf-v1"] #current .books > .book:nth-child(1) > .book-icon {
  --glyph-ratio: 580 / 1103;
  --glyph-size: 216.206897% 113.689937%;
  --glyph-position: 60.089021% 42.384106%;
}
main#main[data-mh-top="shelf-v1"] #current .books > .book:nth-child(2) > .book-icon {
  --glyph-ratio: 1131 / 1212;
  --glyph-size: 110.875332% 103.465347%;
  --glyph-position: 53.658537% 61.904762%;
}
main#main[data-mh-top="shelf-v1"] #current .books > .book:nth-child(3) > .book-icon {
  --glyph-ratio: 1213 / 1182;
  --glyph-size: 103.380049% 106.091371%;
  --glyph-position: 65.853659% 43.055556%;
}
@media (max-width: 1100px) {
  main#main[data-mh-top="shelf-v1"] #current .books > .book > .book-icon::before {
    top: calc(50% + 26px);
  }
}
